param([Parameter(Mandatory)][string]$Launch,[Parameter(Mandatory)][string]$Unused,[switch]$Rebind,[switch]$Consumable,[switch]$Survey,[switch]$Router,[switch]$Equip,[switch]$Overlap,[ValidateRange(0.25,2.0)][double]$RenderScale=1.0,[ValidateRange(0.25,1.0)][double]$EyeRenderScale=1.0,[ValidateRange(0.0,1.0)][double]$DesktopRenderScale=0.0,[switch]$DlssObserve,[switch]$EyeDealias,[switch]$NoEyeTransient,[ValidateRange(-1,60)][int]$DesktopSkip=-1,[switch]$DesktopRender,[switch]$GiOwn)
$ErrorActionPreference='Stop'
& 'S:/stable/Python31011/python.exe' vrmod/tools/run_render_resource_probe.py --launch $Launch --world-live-xr $Unused --live-frames 600 --render-scale $RenderScale @(if($EyeRenderScale -ne 1.0){'--eye-render-scale';$EyeRenderScale}) @(if($DesktopRenderScale -gt 0){'--desktop-render-scale';$DesktopRenderScale}) @(if($DlssObserve){'--world-dlss-observe'}) @(if($EyeDealias){'--world-eye-dealias'}) @(if($NoEyeTransient){'--world-eye-shared-transient'}) @(if($DesktopSkip -ge 0){'--world-desktop-skip';$DesktopSkip}) @(if($DesktopRender){'--world-desktop-render'}) @(if($GiOwn){'--world-gi-own'}) --world-shared-updates-once --world-share-vfx-lights --world-early-xr --world-shared-culling-camera --world-vfx-transparent-observe --world-vfx-transparent-render --world-water-feedback --world-culling-history --world-root-camera first-person --world-camera-modes --world-input-observe --world-input-head-walking --world-endurance --world-equipment-observe --world-head-visibility --world-attachments-observe --world-hands-only --world-motion-hands --world-motion-visual --world-quick-wheel @(if($Rebind){'--world-quick-wheel-rebind'}) @(if($Consumable){'--world-quick-wheel-consumable'}) @(if($Survey){'--world-quick-wheel-survey'}) @(if($Router){'--world-grip-router-wheel'}) @(if($Equip){'--world-grip-router-equip'}) @(if($Overlap){'--world-grip-router-equip-overlap'})
if($LASTEXITCODE -ne 0){throw 'Quick wheel trial failed; preserve logs and close the game normally.'}
